MOTIF_NAME = 'rook_behind_passed_pawn'
MOTIF_DESCRIPTION = 'The side to move has a rook behind its own passed pawn while the opponent has no rook behind their own passed pawn.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def has_passed_pawn(color):
        pawns = board.pieces(chess.PAWN, color)
        opp_pawns = board.pieces(chess.PAWN, not color)
        passed = []
        for sq in pawns:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            passed_flag = True
            for opp_sq in opp_pawns:
                of = chess.square_file(opp_sq)
                if abs(of - f) <= 1:
                    or_ = chess.square_rank(opp_sq)
                    if (color == chess.WHITE and or_ > r) or (color == chess.BLACK and or_ < r):
                        passed_flag = False
                        break
            if passed_flag:
                passed.append(sq)
        return passed

    def rook_behind_own_passed(color):
        passed = has_passed_pawn(color)
        rooks = board.pieces(chess.ROOK, color)
        for rsq in rooks:
            rf = chess.square_file(rsq)
            rr = chess.square_rank(rsq)
            for psq in passed:
                if chess.square_file(psq) != rf:
                    continue
                pr = chess.square_rank(psq)
                if color == chess.WHITE:
                    if rr < pr:
                        return True
                else:
                    if rr > pr:
                        return True
        return False

    stm_has = rook_behind_own_passed(stm)
    opp_has = rook_behind_own_passed(opp)
    return stm_has and not opp_has
